// @vitest-environment jsdom
import {afterEach,expect,it,vi} from 'vitest';
import {dashboardLoadingStateCompilerAnchors as anchors} from '../js/dashboard-loading-state-compiler-anchors.js';
const compiler=vi.hoisted(()=>({html:''}));
vi.mock('../js/components/DashboardLightSunLoading.svelte.html.js',()=>({renderHTML:()=>compiler.html}));
import {renderDashboardLoadingState} from '../js/dashboard-loading-state-presentation.js';
const original=JSON.stringify(anchors),anchor=anchors['light-sun-loading'];
afterEach(()=>{Object.assign(anchor,JSON.parse(original)['light-sun-loading']);});
for(const mode of ['production','development'] as const)it('accepts the complete actual compiler '+mode+' frame',()=>{compiler.html=anchor[mode].html;expect(renderDashboardLoadingState({kind:'light-sun-loading'})).toBe(anchor.nativeHTML);});
const corruptions:{name:string;change:(value:string)=>string}[]=[
 {name:'class',change:x=>x.replace('dashboard-widget-empty','dashboard-widget-wrong')},
 {name:'busy ARIA',change:x=>x.replace('aria-busy="true"','aria-busy="false"')},
 {name:'live ARIA',change:x=>x.replace('aria-live="polite"','aria-live="assertive"')},
 {name:'escaped text',change:x=>x.replace('&amp;','&')},
 {name:'label',change:x=>x.replace('Loading','Ready')},
 {name:'whitespace',change:x=>x.replace('      Loading','     Loading')},
 {name:'tag',change:x=>x.replace('<div','<span')},
 {name:'prefix comment',change:x=>x.replace('<!--[0-->','<!--[1-->')},
 {name:'suffix comment',change:x=>x.slice(0,-1)},
 {name:'extra sibling',change:x=>x+'<div></div>'},
];
for(const corruption of corruptions)it('rejects unauthorized complete compiler '+corruption.name,()=>{compiler.html=corruption.change(anchor.production.html);expect(()=>renderDashboardLoadingState({kind:'light-sun-loading'})).toThrow('Unqualified complete Dashboard loading compiler frame');});
it('rejects an unqualified branch',()=>{expect(()=>renderDashboardLoadingState({kind:'other'} as unknown as Parameters<typeof renderDashboardLoadingState>[0])).toThrow('Unqualified Dashboard loading branch');});
it('rejects altered native-body data even with an intact compiler frame',()=>{compiler.html=anchor.production.html;(anchor as unknown as {nativeHTML:string}).nativeHTML='wrong';expect(()=>renderDashboardLoadingState({kind:'light-sun-loading'})).toThrow('Unqualified native Dashboard loading body');});
it('rejects unauthorized prefix extraction in both qualified modes',()=>{compiler.html=anchor.production.html;for(const mode of ['production','development'] as const)(anchor[mode] as unknown as {prefix:string}).prefix+='x';expect(()=>renderDashboardLoadingState({kind:'light-sun-loading'})).toThrow('Unqualified native Dashboard loading body');});
it('rejects unauthorized suffix extraction in both qualified modes',()=>{compiler.html=anchor.production.html;for(const mode of ['production','development'] as const)(anchor[mode] as unknown as {suffix:string}).suffix+='x';expect(()=>renderDashboardLoadingState({kind:'light-sun-loading'})).toThrow('Unqualified native Dashboard loading body');});
